    ),
    "tallergicReactionContent13": MessageLookupByLibrary.simpleMessage(
      "Monitor Breathing and Consciousness",
    ),
    "tallergicReactionContent14": MessageLookupByLibrary.simpleMessage(
      "Watch the person closely. If breathing stops or the person becomes unresponsive, start CPR immediately.",
    ),
    "tallergicReactionContent15": MessageLookupByLibrary.simpleMessage(
      "Important Notes:",
    ),
    "tallergicReactionContent16": MessageLookupByLibrary.simpleMessage(
      "Epinephrine is the only effective treatment for anaphylaxis.",
    ),
    "tallergicReactionContent17": MessageLookupByLibrary.simpleMessage(
      "Do not give anything to eat or drink during the reaction.",
    ),
    "tallergicReactionContent18": MessageLookupByLibrary.simpleMessage(
      "A second epinephrine dose may be needed after 5–15 minutes.",
    ),
    "tallergicReactionContent19": MessageLookupByLibrary.simpleMessage(
      "Antihistamines may help mild symptoms but are not enough for severe reactions.",
    ),
    "tallergicReactionContent2": MessageLookupByLibrary.simpleMessage(
