    "ufaa_q1_opt1": MessageLookupByLibrary.simpleMessage(
      "Check scene safety and call emergency services if needed",
    ),
    "ufaa_q1_opt2": MessageLookupByLibrary.simpleMessage(
      "Run into traffic immediately",
    ),
    "ufaa_q1_opt3": MessageLookupByLibrary.simpleMessage(
      "Move every casualty at once",
    ),
    "ufaa_q1_opt4": MessageLookupByLibrary.simpleMessage(
      "Start treatment without looking around",
    ),
    "ufaa_q2": MessageLookupByLibrary.simpleMessage(
      "What is a sensible first assessment sequence for an adult casualty?",
    ),
    "ufaa_q2_explanation": MessageLookupByLibrary.simpleMessage(
      "A systematic assessment helps identify immediate life threats.",
    ),
    "ufaa_q2_opt1": MessageLookupByLibrary.simpleMessage(
      "Give food, then ask their name",
    ),
    "ufaa_q2_opt2": MessageLookupByLibrary.simpleMessage(
      "Check safety, response, and normal breathing; call for help and provide appropriate care",
    ),
    "ufaa_q2_opt3": MessageLookupByLibrary.simpleMessage(
      "Move the neck in every direction",
    ),
    "ufaa_q2_opt4": MessageLookupByLibrary.simpleMessage(
      "Wait silently for ten minutes",
    ),
    "ufaa_q3": MessageLookupByLibrary.simpleMessage(
      "A responsive adult refuses help after a minor injury. What should you generally do?",
    ),
    "ufaa_q3_explanation": MessageLookupByLibrary.simpleMessage(
      "A competent adult can usually refuse care; explain and respect their choice.",
    ),
    "ufaa_q3_opt1": MessageLookupByLibrary.simpleMessage(
      "Force treatment on them",
    ),
    "ufaa_q3_opt2": MessageLookupByLibrary.simpleMessage("Ignore their words"),
    "ufaa_q3_opt3": MessageLookupByLibrary.simpleMessage(
      "Respect their decision if they have capacity, explain concerns, and seek help if danger is serious",
    ),
    "ufaa_q3_opt4": MessageLookupByLibrary.simpleMessage(
      "Give medicine secretly",
    ),
    "ufaa_q4": MessageLookupByLibrary.simpleMessage(
      "When should you call emergency services?",
    ),
    "ufaa_q4_explanation": MessageLookupByLibrary.simpleMessage(
      "Recognize emergencies early and activate professional help.",
    ),
    "ufaa_q4_opt1": MessageLookupByLibrary.simpleMessage(
      "Only when there is visible blood",
    ),
    "ufaa_q4_opt2": MessageLookupByLibrary.simpleMessage(
      "Only if the casualty asks twice",
    ),
    "ufaa_q4_opt3": MessageLookupByLibrary.simpleMessage(
      "Never for an unconscious person",
    ),
    "ufaa_q4_opt4": MessageLookupByLibrary.simpleMessage(
      "For life-threatening symptoms such as unresponsiveness, abnormal breathing, severe bleeding, or stroke signs",
    ),
    "ufaa_q5": MessageLookupByLibrary.simpleMessage(
      "Why use gloves or a barrier when possible?",
    ),
    "ufaa_q5_explanation": MessageLookupByLibrary.simpleMessage(
      "Barrier protection reduces exposure risk.",
    ),
    "ufaa_q5_opt1": MessageLookupByLibrary.simpleMessage(
      "To reduce exposure to blood and body fluids",
    ),
    "ufaa_q5_opt2": MessageLookupByLibrary.simpleMessage(
      "To make the casualty sleepy",
    ),
    "ufaa_q5_opt3": MessageLookupByLibrary.simpleMessage(
      "To replace handwashing forever",
    ),
    "ufaa_q5_opt4": MessageLookupByLibrary.simpleMessage(
      "To avoid calling for help",
    ),
    "ufaa_q6": MessageLookupByLibrary.simpleMessage(
      "A casualty is unconscious but breathing normally, and no major trauma is suspected. What may be appropriate?",
    ),
    "ufaa_q6_explanation": MessageLookupByLibrary.simpleMessage(
      "The recovery position can help maintain an open airway in an unconscious breathing person when appropriate.",
    ),
    "ufaa_q6_opt1": MessageLookupByLibrary.simpleMessage("Give them water"),
    "ufaa_q6_opt2": MessageLookupByLibrary.simpleMessage(
      "Leave them face down",
