    "ufaa_q7_opt3": MessageLookupByLibrary.simpleMessage("Give them a snack"),
    "ufaa_q7_opt4": MessageLookupByLibrary.simpleMessage(
      "Wait for their colour to change",
    ),
    "ufaa_q8": MessageLookupByLibrary.simpleMessage(
      "Why should you obtain consent before treating a responsive adult?",
    ),
    "ufaa_q8_explanation": MessageLookupByLibrary.simpleMessage(
      "Explain what you want to do and obtain consent where possible.",
    ),
    "ufaa_q8_opt1": MessageLookupByLibrary.simpleMessage(
      "It is optional in every situation",
    ),
    "ufaa_q8_opt2": MessageLookupByLibrary.simpleMessage(
      "It makes the injury worse",
    ),
    "ufaa_q8_opt3": MessageLookupByLibrary.simpleMessage(
      "It replaces first-aid skills",
    ),
    "ufaa_q8_opt4": MessageLookupByLibrary.simpleMessage(
      "It respects the person\'s autonomy",
    ),
    "ufaa_q9": MessageLookupByLibrary.simpleMessage(
      "A scene becomes unsafe while you are helping. What should you do?",
