    "woundCareIntro": MessageLookupByLibrary.simpleMessage(
      "Proper wound care helps prevent infection and promotes faster healing.",
    ),
    "woundCareMedicalHelp1": MessageLookupByLibrary.simpleMessage(
      "The wound is deep, large, or won’t stop bleeding.",
    ),
    "woundCareMedicalHelp2": MessageLookupByLibrary.simpleMessage(
      "You see signs of infection.",
    ),
    "woundCareMedicalHelp3": MessageLookupByLibrary.simpleMessage(
      "The wound was caused by a dirty or rusty object, or an animal bite.",
    ),
    "woundCareMedicalHelp4": MessageLookupByLibrary.simpleMessage(
      "You have not had a tetanus shot in the last 5 years.",
    ),
    "woundCareMedicalHelpHeading": MessageLookupByLibrary.simpleMessage(
      "When to Seek Medical Help:",
    ),
    "woundCareStep1": MessageLookupByLibrary.simpleMessage(
      "Wash your hands thoroughly before touching the wound.",
    ),
    "woundCareStep2": MessageLookupByLibrary.simpleMessage(
      "Stop the bleeding by applying gentle pressure with a clean cloth.",
    ),
    "woundCareStep3": MessageLookupByLibrary.simpleMessage(
      "Clean the wound with clean water. Avoid using hydrogen peroxide or iodine directly as they may damage tissue.",
    ),
    "woundCareStep4": MessageLookupByLibrary.simpleMessage(
      "Apply an antibiotic ointment to prevent infection.",
    ),
    "woundCareStep5": MessageLookupByLibrary.simpleMessage(
      "Cover the wound with a sterile bandage or dressing.",
    ),
    "woundCareStep6": MessageLookupByLibrary.simpleMessage(
      "Change the dressing daily or whenever it becomes wet or dirty.",
    ),
    "woundCareStep7": MessageLookupByLibrary.simpleMessage(
      "Watch for signs of infection: increased redness, swelling, warmth, pain, or pus.",
    ),
    "woundCareStepsHeading": MessageLookupByLibrary.simpleMessage(
      "Steps for Basic Wound Care:",
    ),
